package com.ganesh.fund;
import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.crypto.password.PasswordEncoder;import java.math.BigDecimal;import java.time.LocalDate;
@Configuration public class DataConfig { @Bean CommandLineRunner seed(UserRepository users,TransactionRepository tx,MemberRepository members,SettingRepository settings,PasswordEncoder enc,@Value("${app.admin.username}")String admin,@Value("${app.admin.password}")String pass){return args->{if(users.findByUsername(admin).isEmpty())users.save(new User(admin,enc.encode(pass),"ADMIN")); if(settings.findById(1L).isEmpty())settings.save(new Setting("Sri Ganesh Chaturthi Committee","2026")); if(members.count()==0){members.save(new Member("Chandra Shekar Manne","President","9876543210"));members.save(new Member("Srinivas Reddy","Vice President","9876543211"));members.save(new Member("Lakshmi Prasad","Secretary","9876543212"));members.save(new Member("Venkatesh Rao","Treasurer","9876543213"));members.save(new Member("Suresh Kumar","Member","9876543214"));} if(tx.count()==0){save(tx,"2026-09-01","add","Anil","Donation",4000);save(tx,"2026-09-02","add","Committee","Committee Collection",5000);save(tx,"2026-09-03","withdraw","Committee","Sound System",1950);save(tx,"2026-09-04","add","Lakshmi","Donation",2500);save(tx,"2026-09-06","withdraw","Committee","Pooja Items",1500);save(tx,"2026-09-08","add","Suresh","Donation",3000);save(tx,"2026-09-10","withdraw","Committee","Decoration",2500);save(tx,"2026-09-11","add","Ramesh","Donation",5000);}};} private void save(TransactionRepository r,String d,String t,String p,String desc,double a){Transaction x=new Transaction();x.date=LocalDate.parse(d);x.type=t;x.person=p;x.description=desc;x.amount=BigDecimal.valueOf(a);r.save(x);} }
